"""Regenerate docs/tool-reference.md from the tools the server registers.

Run after adding a tool or changing a tool's description or parameters:

    uv run python scripts/gen_tool_reference.py

`tests/test_docs.py` fails when the committed file is out of date.
"""

from __future__ import annotations

import sys
from pathlib import Path
from typing import Any

import anyio
from mcp import Client

from office_mcp.server import ServerConfig, build_server

OUT = Path(__file__).resolve().parent.parent / "docs" / "tool-reference.md"

HEADER = """\
<!-- Generated by scripts/gen_tool_reference.py. Do not edit by hand. -->

# Tool reference

Every tool the server registers with all apps enabled. Tools marked
**read-only** are the only ones left with `--read-only`.

The edit ops behind `word_exec` and the anchor ids every tool uses are
documented in the Word guide (`word_read(command="guide")`, or the
`office-mcp://word/guide` resource).
"""


def _type(schema: dict[str, Any]) -> str:
    if "enum" in schema:
        return " \\| ".join(f"`{v}`" for v in schema["enum"])
    if "anyOf" in schema:
        parts = [_type(s) for s in schema["anyOf"] if s.get("type") != "null"]
        return " \\| ".join(parts) if parts else "any"
    kind = schema.get("type")
    if kind == "array":
        return f"{_type(schema.get('items', {}))}[]"
    return kind or "any"


def _cell(text: str) -> str:
    return text.replace("|", "\\|").replace("\n", " ")


def _tool_section(tool: Any) -> str:
    ann = tool.annotations
    kind = "read-only" if ann and ann.read_only_hint else "changes documents or files"
    lines = [f"### `{tool.name}`", "", f"**{tool.title}** ({kind})", "", tool.description, ""]
    props = tool.input_schema.get("properties", {})
    required = set(tool.input_schema.get("required", []))
    if props:
        lines += ["| Parameter | Type | Required | Description |", "| --- | --- | --- | --- |"]
        for name, schema in props.items():
            lines.append(
                f"| `{name}` | {_type(schema)} | {'yes' if name in required else 'no'} "
                f"| {_cell(schema.get('description', ''))} |"
            )
        lines.append("")
    return "\n".join(lines)


async def _tools() -> list[Any]:
    async with Client(build_server(ServerConfig())) as client:
        return (await client.list_tools()).tools


def render() -> str:
    tools = anyio.run(_tools)
    by_app: dict[str, list[Any]] = {}
    for tool in tools:
        by_app.setdefault(tool.name.split("_", 1)[0], []).append(tool)
    titles = {"word": "Word", "excel": "Excel", "ppt": "PowerPoint"}
    parts = [HEADER]
    for app, app_tools in by_app.items():
        parts.append(f"## {titles.get(app, app)}\n")
        parts.extend(_tool_section(t) for t in app_tools)
    return "\n".join(parts).rstrip() + "\n"


def main() -> None:
    text = render()
    if "--check" in sys.argv:
        current = OUT.read_text(encoding="utf-8") if OUT.exists() else ""
        if current != text:
            sys.exit("docs/tool-reference.md is out of date; run scripts/gen_tool_reference.py")
        return
    OUT.write_text(text, encoding="utf-8", newline="\n")
    print(f"wrote {OUT.name}")


if __name__ == "__main__":
    main()
